-- ----------------------------
-- View structure for course_without_previous
-- ----------------------------
DROP VIEW IF EXISTS `course_without_previous`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `course_without_previous` AS select `course`.`Cno` AS `CNO`,`course`.`Cname` AS `CNAME`,`course`.`Cpno` AS `CPNO`,`course`.`Ccredit` AS `CCREDIT` from `course` where (`course`.`Cpno` is not null)  WITH CASCADED CHECK OPTION;

