CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `s_avg_grade` AS select `sc`.`Sno` AS `SNO`,avg(`sc`.`Grade`) AS `AVG(GRADE)` from `sc` group by `sc`.`Sno`;

